INSERT INTO "LandingPage" VALUES('cmvcbochk0000sm5fcp3e06pn','jaw-surgery','جراحی فک (ارتوگناتیک)','جراحی فک در تهران | ارتوگناتیک یک فک و دو فک','جراحی فک با دکتر حامد کرمانی، متخصص جراحی فک و صورت و فلوشیپ کرانیوفاسیال با بیش از ۱۰۶۷ جراحی موفق. اصلاح فک بالا و پایین، جویدن، تنفس و زیبایی پروفایل. رزرو مشاوره: ۰۲۱-۶۶۹۲۱۵۰۰','["جراحی فک","جراحی فک تهران","جراحی ارتوگناتیک","عمل جراحی فک و صورت","جراح فک و صورت","هزینه جراحی فک"]','جراحی فک و صورت','جراحی فک در تهران؛ اصلاح ساختاری فک با دکتر حامد کرمانی','جراحی فک (ارتوگناتیک) ناهنجاری های اسکلتی فک بالا و پایین را اصلاح می کند تا جویدن، گفتار، تنفس و زیبایی پروفایل شما همزمان بهبود یابد. بیش از ۱۰۶۷ جراحی فک موفق با تخصص OMFS و فلوشیپ کرانیوفاسیال.','/images/landing/jaw-surgery-hero.jpg','جراحی فک — نمای تخصصی','[{"title":"جراحی فک چیست و چه مشکلاتی را حل می کند؟","paragraphs":["**جراحی فک** یا جراحی ارتوگناتیک، عملی است که موقعیت استخوان فک بالا (ماکسیلا) یا فک پایین (ماندیبل) را اصلاح می کند تا دو فک دقیقا روی هم بنشینند. وقتی مشکل از دندان نباشد و ریشه در استخوان فک داشته باشد، هیچ مقدار ارتودنسی به تنهایی نمی تواند جویدن و پروفایل را کاملا اصلاح کند؛ در این موارد ترکیب ارتودنسی و جراحی فک راه حل استاندارد جهانی است.","این جراحی فقط برای زیبایی نیست. ناهنجاری اسکلتی فک روی **عملکرد جویدن**، **گفتار**، **تنفس** و حتی **خواب** اثر می گذارد. بسیاری از بیماران با فک عقب‌رفته دچار خروپف و اختلال تنفسی در خواب هستند و با اصلاح موقعیت فک، کیفیت خواب و اکسیژن‌رسانی آن ها بهتر می شود."]},{"title":"چه کسانی کاندید جراحی فک هستند؟","cards":[{"title":"فک پایین جلوآمده (کلاس ۳)","desc":"زیرلب بالاتر از لب پایین قرار نمی گیرد و دندان های پایین جلوی دندان های بالا می افتند؛ رایج ترین دلیل مراجعه."},{"title":"فک عقب‌رفته (کلاس ۲)","desc":"چانه نسبت به بقیه صورت عقب است، خط پروفایل ضعیف می شود و در خواب خروپف و مشکل تنفسی ایجاد می کند."},{"title":"فک بالا کوچک یا بلند","desc":"لبخند لثه ای، عدم نمایش دندان های بالا هنگام لبخند یا افتادگی زاویه صورت از نشانه های آن است."},{"title":"عدم تقارن صورت","desc":"خط میانی فک و چانه از خط مرکز صورت منحرف شده و جویدن یک طرفه ایجاد شده است."},{"title":"مشکل جویدن مزمن","desc":"عدم تماس دندان های جلو، جویدن سخت و فشار غیرطبیعی روی مفصل فک (TMJ)."},{"title":"آپنه خواب ناشی از فک","desc":"در موارد خاص، جابجایی فک پایین و بالا مسیر هوایی را باز می کند و خواب را اصلاح می نماید."}]},{"title":"مراحل جراحی فک از مشاوره تا نتیجه نهایی","steps":["مشاوره و معاینه تخصصی — بررسی اکلوزن، پروفایل و شرح حال کامل توسط دکتر کرمانی.","تصویربرداری و تحلیل — رادیوگرافی سفالومتریک و پانورامیک (و در موارد لازم CBCT) برای طراحی دقیق جابجایی استخوان.","ارتودنسی آماده سازی — معمولا ۶ تا ۱۸ ماه مرتب کردن دندان ها پیش از عمل، هماهنگ با ارتودنتیست.","جراحی زیر بیهوشی عمومی — برش های تمام داخل دهانی (بدون جای جراحی روی صورت) و تثبیت با صفحه و پیچ تیتانیوم.","بستری و دوران بهبودی — معمولا ۱ تا ۲ روز بستری، رژیم مایعات و نرم، و بازگشت به کار در ۲ تا ۳ هفته.","ارتودنسی تکمیلی — چند ماه تنظیم نهایی بایت و سپس برداشتن براکت ها."]},{"title":"چرا دکتر حامد کرمانی برای جراحی فک؟","bullets":["متخصص جراحی فک و صورت (OMFS) — دکترای دندانپزشکی و تخصص از دانشگاه علوم پزشکی مشهد","فلوشیپ جراحی های کرانیوفاسیال از دانشگاه علوم پزشکی تهران","بیش از ۱۰۶۷ جراحی فک، ۳۴۷ پیوند استخوان و ۱۶ سال تجربه جراحی","استادیار سابق دانشگاه های علوم پزشکی شهید بهشتی و مشهد","تجربه بین المللی در بلژیک، آلمان و چین"]}]','فکر می کنید جراحی فک برای شما مناسب است؟','رادیوگرافی خود را در واتسپ مطب بفرستید یا برای مشاوره حضوری تماس بگیرید؛ تشخیص دقیق پس از معاینه و بررسی تصاویر اعلام می شود.','[{"q":"جراحی فک چند ساعت طول می کشد؟","a":"جراحی یک فک معمولا حدود ۲ تا ۳ ساعت و جراحی دو فک (بایمکس) حدود ۳ تا ۵ ساعت زیر بیهوشی عمومی طول می کشد. مدت دقیق به پیچیدگی ناهنجاری و ترکیب مراحل (مثل جنیوپلاستی یا پیوند استخوان) بستگی دارد."},{"q":"عوارض جراحی فک چیست؟","a":"شایع ترین عوارض موقتی هستند: تورم، بی حسی ناحیه لب و چانه که طی هفته ها تا ماه ها برطرف می شود، و خونریزی جزئی. عوارض جدی مانند آسیب دائمی عصب یا عفونت در جراحی های انجام شده توسط جراح باتجربه و در بیمارستان مجهز بسیار نادر است."},{"q":"سن مناسب جراحی فک چه زمانی است؟","a":"بهترین زمان پس از پایان رشد اسکلتی است؛ معمولا ۱۷ تا ۱۸ سالگی برای دختران و ۱۹ تا ۲۰ سالگی برای پسران. در بزرگسالان هیچ محدودیت سنی بالایی وجود ندارد، شرط اصلی سلامت عمومی و کنترل بیماری های زمینه ای است."},{"q":"آیا جراحی فک درد دارد؟","a":"در ۲۴ تا ۴۸ ساعت اول با داروهای تجویزی کنترل می شود و معمولا از روز سوم به بعد به سرعت کاهش می یابد. اکثر بیماران بیش از تورم و خستگی، درد شدید گزارش نمی کنند."},{"q":"هزینه جراحی فک چقدر است؟","a":"طبق تعرفه های منتشرشده این سایت، جراحی های فک حدود ۹۰ تا ۲۴۰ میلیون تومان است و قیمت نهایی به نوع جراحی (یک فک یا دو فک)، بیمارستان و نیاز به پیوند استخوان بستگی دارد. قیمت ها به روزرسانی می شوند؛ برای قیمت دقیق با مطب تماس بگیرید."}]','[{"href":"/chin-surgery","label":"جراحی چانه و جنیوپلاستی"},{"href":"/dental-implant","label":"ایمپلنت دندان"},{"href":"/implant-pasdaran","label":"ایمپلنت دندان در تهران"}]',1,1792238103674);
INSERT INTO "LandingPage" VALUES('cmvcbochn0001sm5fceez4j0k','chin-surgery','جراحی چانه (جنیوپلاستی)','جراحی چانه | اصلاح چانه عقب‌رفته و جلوآمده با جنیوپلاستی','جراحی چانه با دکتر حامد کرمانی — اصلاح چانه عقب‌رفته، جلوآمده، کوتاه و نامتقارن با جنیوپلاستی استخوانی و پروتز. بیش از ۲۴۸ اصلاح چانه موفق. رزرو مشاوره: ۰۲۱-۶۶۹۲۱۵۰۰','["جراحی چانه","عمل چانه","اصلاح فرم چانه","چانه عقب‌رفته","پروتز چانه","جراحی زیبایی چانه"]','جراحی زیبایی چانه','جراحی چانه؛ فرم و هارمونی پروفایل شما را بازتعریف می کنیم','چانه ستون فرج پروفایل است. چانه عقب‌رفته یا جلوآمده هارمونی کل صورت را به هم می زند. با جنیوپلاستی استخوانی و بیش از ۲۴۸ اصلاح چانه موفق، نتیجه ای دائمی و طبیعی دریافت کنید.','/images/landing/chin-surgery-hero.jpg','جراحی چانه و پروفایل','[{"title":"چرا چانه اهمیت دارد؟","paragraphs":["**جراحی چانه** یکی از پرتأثیرترین جراحی های زیبایی ساختاری صورت است؛ چانه با وجود اندازه کوچک، قاب پایینی صورت را تعیین می کند. چانه عقب‌رفته باعث می شود بینی بزرگ تر دیده شود، زاویه گردن و فک محو شود و زیرچانه پر از چربی به نظر برسد. چانه جلوآمده هم پروفایل را مردانه و خشمگین نشان می دهد. اصلاح دقیق موقعیت چانه، کل هارمونی صورت را بدون دست زدن به سایر اجزا تغییر می دهد.","علاوه بر زیبایی، در موارد عدم تقارن یا کمبود استخوان چانه، اصلاح آن روی عملکرد لب پایین و تعادل عضلات ناحیه هم اثر مثبت می گذارد."]},{"title":"گزینه های جراحی چانه؛ کدام برای شما مناسب است؟","cards":[{"title":"جنیوپلاستی اسلایدینگ (استخوانی)","desc":"استخوان چانه خودتان برش خورده و به موقعیت ایده آل جابجا و با صفحه و پیچ تثبیت می شود؛ نتیجه دائمی، بدون خطر جابجایی یا دفع بدن."},{"title":"پروتز چانه","desc":"ایمپلنت سازگار با بدن روی استخوان چانه قرار می گیرد؛ مناسب کمبودهای خفیف تا متوسط حجم که نیازی به جابجایی استخوان ندارند."},{"title":"اصلاح عمودی چانه","desc":"چانه های خیلی کوتاه یا بلند با کاهش یا افزایش ارتفاع استخوان اصلاح می شوند و نسبت طلایی یک سوم پایینی صورت بازسازی می گردد."},{"title":"اصلاح عدم تقارن","desc":"انحراف چانه به یک سمت با برش و جابجایی سه بعدی اصلاح و خط میانی صورت بازگردانده می شود."},{"title":"ترکیب با لیپوساکشن زیرچانه","desc":"در بیمارانی که زیرچانه چربی اضافه دارند، در همان جلسه چربی جمع می شود تا زاویه فک و گردن شارپ شود."},{"title":"ترکیب با جراحی دو فک","desc":"در اصلاحات کامل پروفایل، جنیوپلاستی در همان جلسه جراحی فک انجام می شود تا هارمونی سه بعدی صورت کامل گردد."}]},{"title":"مسیر شما تا پروفایل جدید","steps":["مشاوره و آنالیز پروفایل — بررسی یک سوم پایینی صورت از نمای روبه‌رو و نیمرخ.","تصویربرداری — سفالومتری برای تعیین میزان دقیق جابجایی (ملی‌متر به ملی‌متر).","عمل زیر بیهوشی عمومی یا بیهوشی موضعی+آرام بخشی (برای پروتز ساده) — برش کاملا داخل دهانی.","بهبودی — تورم ۱۰ تا ۱۴ روزه، رژیم نرم چند روزه و بازگشت به اجتماعات پس از حدود ۱۰ روز.","کنترل و رادیوگرافی پیگیری برای اطمینان از جوش خوردن استخوان."]}]','پروفایل خود را با مشاوره تخصصی بسنجید','عکس نیمرخ خود را در واتسپ ارسال کنید یا برای معاینه حضوری تماس بگیرید؛ طرح درمان دقیق پس از بررسی تصاویر و معاینه ارائه می شود.','[{"q":"جراحی چانه چه تفاوتی با تزریق فیلر دارد؟","a":"فیلر موقتی است (۶ تا ۱۸ ماه) و فقط حجم می دهد؛ جنیوپلاستی استخوان چانه را با استخوان خودتان جابجا و تثبیت می کند و نتیجه دائمی و طبیعی دارد. برای اصلاح اسکلتی واقعی پروفایل، جراحی تنها راهحل قطعی است."},{"q":"جراحی چانه چند روز نقاهت دارد؟","a":"تورم روزهای ۲ تا ۴ حداکثر است و طی ۲ هفته عمدتا فرو می نشیند. اکثر بیماران پس از ۷ تا ۱۰ روز می توانند فعالیت اجتماعی عادی داشته باشند؛ برش کاملا داخل دهانی است و جای جراحی دیده نمی شود."},{"q":"آیا جراحی چانه بی خطر است؟","a":"در دست جراح متخصص فک و صورت، عوارض جدی بسیار نادر است. بی حسی موقت ناحیه چانه به دلیل نزدیکی به عصب ذهنی ممکن است چند هفته طول بکشد و در اکثریت قریب به اتفاق موارد کاملا برطرف می شود."},{"q":"چانه عقب‌رفته فقط با جراحی چانه حل می شود؟","a":"بستگی به علت دارد. اگر مشکل فقط از استخوان چانه باشد، جنیوپلاستی کافی است؛ اما اگر عقب‌رفتگی از فک پایین باشد، اصلاح کامل پروفایل ممکن است نیاز به جراحی فک پایین یا ترکیب آن با جنیوپلاستی داشته باشد که در معاینه مشخص می شود."},{"q":"قیمت جراحی چانه چقدر است؟","a":"هزینه به نوع عمل (جنیوپلاستی استخوانی، پروتز یا ترکیب با جراحی فک) و بیمارستان بستگی دارد. تعرفه های به روز را با تماس با مطب ۰۲۱-۶۶۹۲۱۵۰۰ استعلام کنید."}]','[{"href":"/jaw-surgery","label":"جراحی فک (ارتوگناتیک)"},{"href":"/dental-implant","label":"ایمپلنت دندان"},{"href":"/implant-pasdaran","label":"ایمپلنت دندان در تهران"}]',1,1792238009863);
INSERT INTO "LandingPage" VALUES('cmvcbochp0002sm5f07ggcie7','dental-implant','ایمپلنت دندان','ایمپلنت دندان در تهران | برندهای آلمانی، سوئیسی و آمریکایی','ایمپلنت دندان با دکتر حامد کرمانی، متخصص جراحی فک و صورت — بیش از ۵۰۰۰ ایمپلنت موفق. برندهای DXL آلمان، SPI سوییس، BICON آمریکا، CIS کره و ایمپلنت زایگوماتیک. تماس: ۰۲۱-۶۶۹۲۱۵۰۰','["ایمپلنت دندان","ایمپلنت دندان تهران","قیمت ایمپلنت دندان","کاشت دندان","بهترین دکتر ایمپلنت تهران","ایمپلنت فوری"]','ایمپلنت و بازسازی فک','ایمپلنت دندان در تهران؛ دائمی ترین راه بازگشت لبخند','بیش از ۵۰۰۰ ایمپلنت موفق توسط متخصص جراحی فک و صورت با فلوشیپ کرانیوفاسیال — از ایمپلنت تک دندان تا بازسازی کامل فک با برندهای معتبر آلمانی، سوئیسی و آمریکایی.','/images/landing/dental-implant-hero.jpg','ایمپلنت دندان','[{"title":"چرا ایمپلنت دندان بهترین جایگزین است؟","paragraphs":["**ایمپلنت دندان** یک ریشه مصنوعی تیتانیومی است که داخل استخوان فک قرار می گیرد و مانند دندان طبیعی عمل می کند. برخلاف پل، دندان های مجاور تراش نمی خورند و برخلاف دست دندان، هیچ حرکتی ندارند. تیتانیوم با استخوان یکپارچه می شود (استئوانکژنشن) و پایه ای محکم برای روکش سرامیکی می سازد.","نکته کلیدی: جراح ایمپلنت باید هم با **استخوان فک** و هم با **بافت نرم** تسلط کامل داشته باشد. به عنوان متخصص جراحی فک و صورت، دکتر کرمانی موارد پیچیده — تحلیل شدید استخوان، سینوس‌های پایین، نیاز به پیوند استخوان و بازسازی پس از تومور یا ضربه — را با تجربه ۳۴۷ پیوند استخوان مدیریت می کند."]},{"title":"برندهای ایمپلنت ارائه شده در مطب","cards":[{"title":"DXL — آلمان","desc":"ساخت آلمانی با کیفیت بالا و سطح تماس استخوانی بهینه؛ انتخاب محبوب برای دوام بلندمدت."},{"title":"SPI — سوییس","desc":"تکنولوژی سوئیسی با دقت ساخت بالا؛ مناسب بیمارانی که کیفیت اروپایی می خواهند."},{"title":"BICON — آمریکا","desc":"طراحی بدون پیچ و بدون سمان، هماهنگ با لثه؛ تجربه چند دهه ای در دنیا."},{"title":"CIS — کره","desc":"گزینه اقتصادی‌تر با کیفیت قابل قبول؛ محبوب برای درمان چند واحدی."},{"title":"ایمپلنت زایگوماتیک","desc":"ویژه فک بالا با تحلیل شدید استخوان — لنگر در استخوان گونه بدون نیاز به پیوند استخوان."},{"title":"ایمپلنت فوری","desc":"در موارد انتخابی، همزمان با کشیدن دندان ایمپلنت گذاشته می شود تا زمان درمان کوتاه شود."}]},{"title":"مراحل کاشت ایمپلنت","steps":["مشاوره و CBCT — اندازه گیری دقیق استخوان و طراحی سه بعدی موقعیت ایمپلنت.","کاشت ایمپلنت زیر بی حسی موضعی (۱۰ تا ۳۰ دقیقه برای هر واحد) — برش کوچک و بخیه.","دوره استئوانکژنشن — ۲ تا ۴ ماه یکپارچگی ایمپلنت با استخوان (در موارد خاص ایمپلنت فوری).","ایجاد ایمپلنت ثانوی و قالب‌گیری از لثه برای روکش طبیعی.","نصب روکش نهایی و آموزش بهداشت اختصاصی + کنترل های دوره ای."]}]','دندان های از دست رفته خود را بازگردانید','رادیوگرافی یا عکس دندان های خود را در واتسپ بفرستید تا پیش بررسی رایگان انجام شود؛ سپس برای جلسه مشاوره و CBCT وقت بگیرید.','[{"q":"ایمپلنت دندان چند سال دوام دارد؟","a":"با بهداشت مناسب و کنترل دوره ای، ریشه ایمپلنت می تواند مادام العمر بماند و روکش آن ۱۵ تا ۲۰ سال یا بیشتر کار کند. سیگار و دیابت کنترل نشده مهم ترین عوامل کوتاه کردن عمر ایمپلنت هستند."},{"q":"قیمت ایمپلنت دندان چقدر است؟","a":"طبق تعرفه های منتشرشده این سایت، هر واحد ایمپلنت حدود ۲۴ تا ۱۱۰ میلیون تومان است که به برند (DXL آلمان، CIS کره، SPI سوییس، BICON آمریکا)، نیاز به پیوند استخوان و جنس روکش بستگی دارد. قیمت ها به روزرسانی می شوند."},{"q":"آیا ایمپلنت درد دارد؟","a":"کاشت ایمپلنت زیر بی حسی موضعی انجام می شود و در حین کار دردی احساس نمی کنید. درد بعد از عمل معمولا خفیف‌تر از کشیدن دندان است و چند روز با مسکن کنترل می شود."},{"q":"اگر استخوان فک من تحلیل رفته باشد چه؟","a":"با پیوند استخوان یا سینوس لیفت اغلب می توان بستر مناسب ساخت. در تحلیل شدید فک بالا، ایمپلنت زایگوماتیک بدون نیاز به پیوند استخوان، از استخوان گونه لنگر می گیرد و درمان را چند ماه کوتاه تر می کند."},{"q":"از کشیدن دندان تا ایمپلنت چقدر فاصله می افتد؟","a":"معمولا ۲ تا ۳ ماه برای جوش خوردن لثه لازم است؛ در شرایط مناسب ایمپلنت فوری همزمان با کشیدن انجام می شود. تصمیم نهایی بر اساس CBCT و وضعیت بافت گرفته می شود."}]','[{"href":"/implant-pasdaran","label":"ایمپلنت دندان در تهران و پاسداران"},{"href":"/jaw-surgery","label":"جراحی فک (ارتوگناتیک)"},{"href":"/chin-surgery","label":"جراحی چانه"}]',1,1792238009866);
INSERT INTO "LandingPage" VALUES('cmvcbochr0003sm5fa33i5pu7','implant-pasdaran','ایمپلنت پاسداران و شمال تهران','ایمپلنت دندان در تهران | دسترسی آسان از پاسداران و شمال تهران','ایمپلنت دندان با متخصص جراحی فک و صورت — بیش از ۵۰۰۰ ایمپلنت و ۳۴۷ پیوند استخوان موفق. مطب در مرکز تهران با دسترسی آسان از پاسداران، نیاوران و مناطق شمالی. تماس: ۰۲۱-۶۶۹۲۱۵۰۰','["ایمپلنت پاسداران","ایمپلنت دندان تهران","دکتر ایمپلنت شمال تهران","کاشت دندان پاسداران","هزینه ایمپلنت تهران","ایمپلنت دیجیتال تهران"]','ایمپلنت دندان در تهران','ایمپلنت دندان؛ متخصص جراحی فک و صورت، دسترسی آسان از پاسداران و شمال تهران','بیش از ۵۰۰۰ ایمپلنت موفق و ۳۴۷ پیوند استخوان توسط دکتر حامد کرمانی. پیش بررسی رایگان رادیوگرافی در واتسپ، طرح درمان شفاف و برندهای معتبر آلمانی، سوئیسی و آمریکایی.','/images/landing/implant-pasdaran-hero.jpg','ایمپلنت دندان در تهران','[{"title":"ایمپلنت دندان را به چه جراحی بسپاریم؟","paragraphs":["ایمپلنت یک عمل **جراحی** است، نه صرفا یک کار دندانپزشکی؛ به همین دلیل جراح آن باید تسلط کامل بر آناتومی استخوان فک، عصب‌ها و سینوس ها داشته باشد. دکتر حامد کرمانی، متخصص جراحی فک و صورت (OMFS) و دارنده فلوشیپ جراحی های کرانیوفاسیال از دانشگاه علوم پزشکی تهران، علاوه بر ایمپلنت‌های معمول، **موارد پیچیده** — تحلیل شدید استخوان، ایمپلنت زایگوماتیک، پیوند استخوان، سینوس لیفت و بازسازی پس از تومور و ضربه — را نیز با تجربه بین المللی انجام می دهد.","مطب در تقاطع جمالزاده (بلوار کشاورز) قرار دارد و برای ساکنان پاسداران، نیاوران، الهیه و مناطق شمالی تهران با یک مسیر مستقیم قابل دسترسی است. برای کاهش مراجعات تکراری، رادیوگرافی شما پیش از حضور در واتسپ بررسی می شود."]},{"title":"خدمات ایمپلنت در این مطب","cards":[{"title":"ایمپلنت تک دندان","desc":"جایگزینی یک دندان بدون تراش دندان های مجاور — نتیجه طبیعی و ماندگار."},{"title":"پل ایمپلنت‌پایه","desc":"بازسازی چند دندان متوالی با تعداد کمتر ایمپلنت و هزینه بهینه."},{"title":"بازسازی بی دندانی کامل","desc":"پروتز ثابت روی ایمپلنت یا پروتز قابل جدا شدن — بازگشت قدرت جویدن."},{"title":"ایمپلنت زایگوماتیک","desc":"راه حل فک بالا با تحلیل شدید — لنگر در استخوان گونه، بدون پیوند استخوان و با نقاهت کوتاه."},{"title":"پیوند استخوان و سینوس لیفت","desc":"ساخت بستر مناسب برای ایمپلنت در نواحی تحلیل رفته — بیش از ۳۴۷ پیوند موفق."},{"title":"ایمپلنت فوری","desc":"در موارد مناسب، همزمان با کشیدن دندان ایمپلنت گذاشته می شود تا ماه ها صبر حذف شود."}]},{"title":"مسیر درمان شما","steps":["ارسال رادیوگرافی در واتسپ — پیش بررسی رایگان و پاسخ شفاف درباره امکان درمان.","جلسه مشاوره و CBCT در مطب — طراحی دقیق تعداد، موقعیت و برند ایمپلنت با اعلام هزینه کتبی.","جراحی کاشت — زیر بی حسی موضعی و در موارد کلینیک‌پسند با آرام بخشی.","دوره جوش خوردن ۲ تا ۴ ماهه با کنترل دوره ای.","روکش نهایی و پیگیری سلامت ایمپلنت در ویزیت های شش ماهه."]}]','رادیوگرافی خود را بفرستید؛ پاسخ تخصصی بگیرید','تصویر پانورامیک یا CBCT خود را در واتسپ ارسال کنید تا پیش بررسی شود؛ سپس برای جلسه مشاوره حضوری و طرح درمان دقیق وقت بگیرید.','[{"q":"مطب دکتر کرمانی کجاست و از پاسداران چطور بروم؟","a":"مطب در بلوار کشاورز، تقاطع جمالزاده، ساختمان پزشکان کوثر، طبقه ۳ واحد ۱۲ قرار دارد؛ از مناطق پاسداران، نیاوران و الهیه با خودرو در زمان ترافیک معمول حدود ۲۰ تا ۳۵ دقیقه فاصله دارید و امکان ارسال رادیوگرافی اولیه در واتسپ وجود دارد تا سفرهای تکراری کم شود."},{"q":"قبل از مراجعه حضوری چه چیزی را بفرستم؟","a":"رادیوگرافی پانورامیک یا CBCT و عکس ناحیه بدون دندان را در واتسپ مطب (۰۹۳۸-۲۰۸۰۲۷۰) ارسال کنید. پیش بررسی رایگان انجام می شود و در جلسه حضوری مستقیم وارد طرح درمان و زمان‌بندی می شوید."},{"q":"ایمپلنت با پیوند استخوان چند روز وقت می گیرد؟","a":"خود کاشت ایمپلنت معمولا کمتر از یک ساعت برای چند واحد است. اگر پیوند استخوان یا سینوس لیفت لازم باشد، دوره جوش خوردن ۴ تا ۶ ماه اضافه می شود. در تحلیل شدید فک بالا، ایمپلنت زایگوماتیک بدون پیوند استخوان و با نقاهت کوتاه تر انجام می شود."},{"q":"برای چند دندان از دست رفته هم ایمپلنت می شود؟","a":"بله؛ از تک دندان تا بازسازی کامل فک. برای چند دندان متوالی، پل ایمپلنت‌پایه تعداد ایمپلنت موردنیاز را کاهش می دهد و برای بی دندانی کامل، درمان های فیکس ثابت یا پروتز متحرک روی ایمپلنت ارائه می شود."},{"q":"هزینه ایمپلنت در تهران چقدر است؟","a":"هر واحد ایمپلنت طبق تعرفه های همین سایت حدود ۲۴ تا ۱۱۰ میلیون تومان است که به برند ایمپلنت، نیاز به پیوند استخوان و جنس روکش بستگی دارد. قیمت ها به روزرسانی می شوند؛ استعلام دقیق با مطب تماس بگیرید."}]','[{"href":"/dental-implant","label":"ایمپلنت دندان در تهران"},{"href":"/jaw-surgery","label":"جراحی فک (ارتوگناتیک)"},{"href":"/chin-surgery","label":"جراحی چانه"}]',1,1792238009867);
