INSERT INTO "Service" VALUES('cmvc9tsrv0001smpf1b3wtwkn','jaw-surgery','جراحی یک فک','Orthognathic — Single Jaw','اصلاح ناهنجاری های فک بالا یا پایین به صورت مجزا؛ بهبود عملکرد گاز گرفتن، تکلم و تناسب چهره با جراحی ارتوگناتیک دقیق و برنامه ریزی سه بعدی.','/images/case-1.jpg','["اصلاح عقب رفتگی یا جلو آمدگی فک","بهبود اکلوژن (جفت شدن دندان ها)","هماهنگ با درمان ارتودنسی"]',0,1);
INSERT INTO "Service" VALUES('cmvc9tsrw0002smpf4swyov0q','bimax','جراحی دو فک','Bimaxillary Surgery','جراحی همزمان فک بالا و پایین (بایمکس) برای اصلاح کامل روابط فکی، بهبود تنفس، ظاهر پروفایل و لبخند در پرونده های پیچیده تر.','/images/case-4.jpg','["اصلاح همزمان فک بالا و پایین","بهبود پروفایل و تناسب صورت","برنامه ریزی دیجیتال قبل از عمل"]',1,1);
INSERT INTO "Service" VALUES('cmvc9tsrx0003smpfiri6u4jt','blepharoplasty','بلفاروپلاستی','Blepharoplasty','جراحی پلک برای رفع پف و افتادگی پلک بالا و پایین؛ جوانسازی نگاه با برش های ظریف و پنهان در چین طبیعی پلک.','/images/blepharo-2.jpg','["رفع پف و کیسه های زیر چشم","اصلاح افتادگی پلک بالا","برش پنهان در چین طبیعی پلک"]',2,1);
INSERT INTO "Service" VALUES('cmvc9tsry0004smpfe9rlutn9','genioplasty','جنیوپلاستی (جراحی چانه)','Genioplasty','اصلاح فرم، اندازه و موقعیت چانه؛ جلو بردن، عقب بردن یا کاهش عرض چانه برای رسیدن به تعادل در پروفایل صورت.','/images/case-6.jpg','["اصلاح عقب رفتگی چانه","کاهش یا افزایش طول چانه","تقویت خط جاول (Jawline)"]',3,1);
INSERT INTO "Service" VALUES('cmvc9tsry0005smpfz5x3w778','implant','ایمپلنت (کاشت دندان)','Dental Implants','کاشت دندان با برندهای معتبر جهانی، ایمپلنت های زایگوماتیک برای فک به شدت تحلیل رفته و جراحی های پیشرفته داخل دهان.','/images/case-9.jpg','["ایمپلنت برندهای آلمان، سوییس، آمریکا و کره","ایمپلنت زایگوماتیک (استرومن و ...)","سینوس لیفت و پیوند استخوان (GBR)"]',4,1);
INSERT INTO "Service" VALUES('cmvc9tsrz0006smpfbeeqmj7w','reconstruction','بازسازی فک','Jaw Reconstruction','بازسازی کامل فک بالا و پایین پس از تحلیل شدید، تومور یا تصادف؛ بازگرداندن عملکرد جویدن و زیبایی چهره با پروتزهای مفصل فک.','/images/case-8.jpg','["بازسازی فک بالا با ایمپلنت","پروتز مفصل گیجگاهی فک (TMJ)","پروتزهای شخصی سازی شده"]',5,1);
